const ORBIT_ROUTES={"student-dashboard.html":"../student-dashboard/student-dashboard.html","channels.html":"../channels/channels.html","channel.html":"../channel/channel.html","teacher-studio.html":"../teacher-studio/teacher-studio.html","teacher-profile.html":"../teacher-profile/teacher-profile.html","teachers.html":"../teacher-directory/teacher-directory.html","class-details.html":"../class-details/class-details.html","lessons.html":"../lessons/lessons.html","lesson.html":"../lesson/lesson.html","practice.html":"../practice/practice.html","lab.html":"../lab/lab.html","quiz.html":"../quiz/quiz.html","result.html":"../result/result.html","achievements.html":"../achievements/achievements.html","exchange.html":"../exchange/exchange.html","login.html":"../login/login.html","messages.html":"../channels/channels.html","index.html":"../student-dashboard/student-dashboard.html"};
function orbitRoute(url){if(url.startsWith('../'))return url;const match=url.match(/^([^?#]+)(.*)$/);return match?(ORBIT_ROUTES[match[1]]||match[1])+match[2]:url;}
'use strict';
const storage={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
function parsed(k){try{return JSON.parse(storage.get(k))}catch{return null}}
const legacy=parsed('orbitUser')||parsed('currentUser')||parsed('user')||parsed('student')||{};
let state=Object.assign({lang:storage.get('orbitLanguage')||storage.get('language')||'ar',theme:storage.get('orbitTheme')||storage.get('theme')||'light',mood:storage.get('orbitMood')||'fun',name:legacy.name||legacy.fullName||storage.get('studentName')||storage.get('orbitStudentName')||'Lina',xp:1280,done:[],quiz:null},parsed('orbit.student.v1')||{},{name:OrbitProfiles.current()?.name||legacy.name});
state.lang=['ar','en'].includes(state.lang)?state.lang:'en';state.done=Array.isArray(state.done)?state.done:[];
const page="teacher-profile";
const t=(en,ar)=>state.lang==='ar'?ar:en;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){storage.set('orbit.student.v1',JSON.stringify({...state,name:OrbitProfiles.current()?.name||state.name}));storage.set('orbitLanguage',state.lang);storage.set('orbitTheme',state.theme);storage.set('orbitMood',state.mood);storage.set('studentName',state.name)}
function toast(s){const el=document.getElementById('toast');el.textContent=s;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500)}
const icon=(s,c='')=>`<span class="icon ${c}" aria-hidden="true">${s}</span>`;
const btn=(label,url,cls='')=>`<a class="btn ${cls}" href="${url}">${label}</a>`;
function award(id,xp){if(!state.done.includes(id)){state.done.push(id);state.xp+=xp;save();toast(t(`Great work! +${xp} XP`,`أحسنت! +${xp} نقطة XP`))}}
function dashboard(){return `<section class="hero"><div><span class="pill">♨ ${t('5 day streak','سلسلة إنجاز 5 أيام')}</span><h1>${t('Hi','مرحبًا')} ${esc(state.name)}, ${t('ready for today?','جاهز لليوم؟')}</h1><p>${t('Finish two tasks to hit your daily goal and earn 80 XP. One homework is late, start there.','أنجز مهمتين لتصل لهدفك اليومي وتكسب 80 XP. لديك واجب متأخر، ابدأ به.')}</p><div class="actions">${btn('▷ '+t('Continue learning','تابع التعلم'),'../lesson/lesson.html','gold-button')}${btn('⚒ '+t('Daily challenge','التحدي اليومي'),'../practice/practice.html','secondary')}</div></div><div class="ring"><div><strong>${Math.min(100,60+state.done.length*10)}%</strong><small>${t('daily goal','الهدف اليومي')}</small></div></div></section>
<section class="stats" aria-label="${t('Your statistics','إحصائياتك')}">${[["▣","rose",t('1 late','واجب متأخر'),'pink',Math.max(0,3-state.done.filter(x=>x==='homework'||x==='practice').length),t('tasks this week','مهام هذا الأسبوع')],["◎","mint",'+4%','green','76%',t('your average','معدلك')],["ϟ","orange",t('+120 today','+120 اليوم'),'gold',state.xp.toLocaleString(),t('XP this term','نقاط هذا الفصل')],["♙","",t('2 new','2 جديدة'),'violet',9+Number(state.done.includes('quiz')),t('badges unlocked','شارات مكتسبة')]].map(s=>`<div class="card stat"><div class="stat-top">${icon(s[0],s[1])}<span class="pill ${s[3]}">${s[2]}</span></div><strong>${s[4]}</strong><span class="muted">${s[5]}</span></div>`).join('')}</section>
<div class="columns"><div class="stack"><section class="card"><div class="card-title"><h2>${t('What to do next','ماذا تفعل الآن؟')}</h2><span class="pill gold">ϟ 80 XP ${t('available','متاحة')}</span></div><div class="muted">${t('Sorted by what matters today.','مرتبة حسب الأولوية اليوم.')}</div>
<div class="task ${state.done.includes('homework')?'':'late'}">${icon('◴','rose')}<div class="task-text"><h3>${t('Maths worksheet 5','ورقة الرياضيات 5')}</h3><p>${state.done.includes('homework')?t('Submitted — well done!','تم التسليم — أحسنت!'):t('Was due yesterday, you can still submit','كان موعدها أمس، ما زال بإمكانك التسليم')}</p></div><span class="pill gold">ϟ 30 XP</span>${btn(t('Finish now','أكمل الآن'),'../practice/practice.html?task=homework')}</div>
<div class="task">${icon('▤','orange')}<div class="task-text"><h3>${t("Homework 3: Newton’s second law",'الواجب 3: قانون نيوتن الثاني')}</h3><p>${t('Physics, Grade 9A, due tomorrow','الفيزياء، الصف 9A، موعده غدًا')}</p></div><span class="pill gold">ϟ 50 XP</span>${btn(t('Start','ابدأ'),'../practice/practice.html')}</div>
<div class="task">${icon('♜','blue')}<div class="task-text"><h3>${t('Quiz: forces','اختبار: القوى')}</h3><p>${state.quiz?t('Your result is ready','نتيجتك جاهزة'):t('Test what you have learned','اختبر ما تعلمته')}</p></div>${btn(t('Open','افتح'),state.quiz?'../result/result.html':'../quiz/quiz.html','outline')}</div>
<div class="task">${icon('♙','mint')}<div class="task-text"><h3>${t('Homework 2 was graded: 82%','تم تقييم الواجب 2: ‏82%')}</h3><p>${t('Mr. Khaled left you a note','ترك لك الأستاذ خالد ملاحظة')}</p></div><button class="btn outline" data-action="feedback">${t('See result','عرض النتيجة')}</button></div></section>
<section class="card"><div class="card-title"><h2>${t('Pick up where you left off','تابع من حيث توقفت')}</h2><a class="link" href="../lessons/lessons.html">${t('All lessons','جميع الدروس')}</a></div><div class="lesson-grid">${lessonTile(t("Newton’s laws",'قوانين نيوتن'),t('Intermediate level','المستوى المتوسط'),'⚛',60,'../lesson/lesson.html',t('3 of 5 parts','3 من 5 أجزاء'),20)}${lessonTile(t('Reading force graphs','قراءة منحنيات القوى'),t('Beginner level','المستوى المبتدئ'),'⌁',25,'../lesson/lesson.html?topic=graphs',t('1 of 4 parts','1 من 4 أجزاء'),35)}</div><div class="lab-banner">${icon('♧')}<div class="task-text"><h3>${t('Try the lab: force and acceleration','جرّب المختبر: القوة والتسارع')}</h3><p>${t('Change the mass and watch what happens. 5 minutes','غيّر الكتلة وراقب ما يحدث. 5 دقائق')}</p></div><span class="pill green">ϟ 15 XP</span>${btn(t('Try the lab','جرّب المختبر'),'../lab/lab.html')}</div></section></div>
<div class="stack right-stack"><section class="card"><div class="card-title"><h2>${t('Class leaderboard','متصدرو الصف')}</h2><small class="muted">${t('This week','هذا الأسبوع')}</small></div>${[['RM','Rami M.',1640],['OK','Omar K.',1410],[initials(),t('You','أنت'),state.xp]].sort((a,b)=>b[2]-a[2]).map((r,i)=>`<div class="rank ${r[1]===t('You','أنت')?'you':''}"><span class="place">${i+1}</span><span class="avatar">${r[0]}</span><span>${r[1]}</span><span class="points">${r[2].toLocaleString()}</span></div>`).join('')}<span class="muted">${t('Keep learning to climb the ranks.','واصل التعلم لتتقدم في الترتيب.')}</span></section>
<section class="card"><div class="card-title"><h2>${t('Your badges','شاراتك')}</h2><a class="link" href="../achievements/achievements.html">${t('See all 24','عرض الـ24')}</a></div><div class="badges">${badge('♨','#ffa500','5',t('day streak','أيام متتالية'))}${badge('♧','#8235f8','Lab',t('explorer','مستكشف'))}${badge('✓','#0cbc8b','10',t('tasks','مهام'))}${badge('♧','#bcc6d7',t('Perfect','أسبوع'),t('week','مثالي'))}</div></section>
<section class="card"><div class="card-title"><h2>${t('From the exchange','من سوق التبادل')}</h2><a href="../exchange/exchange.html" class="link">${t('Browse','تصفح')}</a></div><a href="../exchange/exchange.html" class="exchange-row">${icon('▣','blue')}<div><h3>${t('Physics 9 textbook','كتاب فيزياء 9')}</h3><small>${t('Good condition','بحالة جيدة')}</small></div><b>5 JD</b></a><a href="../exchange/exchange.html" class="exchange-row">${icon('◇','mint')}<div><h3>${t('Geometry set','طقم هندسة')}</h3><small>${t('For lending','للإعارة')}</small></div><b>3 JD</b></a></section></div></div>`}
function lessonTile(title,sub,symbol,progress,url,parts,xp){return `<a class="lesson-tile" href="${url}"><div class="lesson-top">${icon(symbol)}<div><h3>${title}</h3><span class="muted">${sub}</span></div></div><div class="bar"><span style="width:${progress}%"></span></div><div class="lesson-meta"><span>${parts}</span><b>+${xp} XP ${t('left','متبقية')}</b></div></a>`}
function badge(symbol,color,label,sub){return `<div class="badge"><span class="icon" style="background:${color}">${symbol}</span><small>${label}<br>${sub}</small></div>`}
function initials(){return esc(state.name.trim().split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase())}
const stages=['class-details','lesson','practice','lab','quiz','result'];
function cycleNav(){return `<nav class="cycle-nav">${stages.map((s,i)=>`<a href="${orbitRoute(s+'.html')}" class="${page===s?'active':''}">${i+1}. ${[t('Class','الصف'),t('Lesson','الدرس'),t('Practice','التدريب'),t('Lab','المختبر'),t('Quiz','الاختبار'),t('Result','النتيجة')][i]}</a>`).join('')}</nav>`}
function contentPage(){let body='',title='';const homework=new URLSearchParams(location.search).get('task')==='homework';const graphs=new URLSearchParams(location.search).get('topic')==='graphs';
if(page==='class-details'||page==='lessons'){title=t('Physics 11 · Your learning space','فيزياء 11 · مساحة تعلمك');body=`<section class="hero"><div><span class="pill">${t('Mr. Khaled · Grade 11','الأستاذ خالد · الصف 11')}</span><h1>${t('A little progress, every day.','خطوة صغيرة، كل يوم.')}</h1><p>${t('Unit 2: Forces and motion · 3 of 5 lessons completed','الوحدة 2: القوى والحركة · أنجزت 3 من 5 دروس')}</p>${btn(t('Continue lesson','تابع الدرس'),'../lesson/lesson.html','gold-button')}</div>${icon('⚛')}</section><div class="lesson-grid">${lessonTile(t("Newton’s laws",'قوانين نيوتن'),t('Learn with examples','تعلم مع الأمثلة'),'⚛',60,'../lesson/lesson.html','3 / 5',20)}${lessonTile(t('Reading force graphs','قراءة منحنيات القوى'),t('Discover the relationship','اكتشف العلاقة'),'⌁',25,'../lesson/lesson.html?topic=graphs','1 / 4',35)}</div><p>${btn(t('Practice homework','تدرب على الواجب'),'../practice/practice.html')} ${btn(t('Interactive lab','المختبر التفاعلي'),'../lab/lab.html')}</p>`}
if(page==='lesson'){title=graphs?t('Reading force graphs','قراءة منحنيات القوى'):t("Newton’s second law",'قانون نيوتن الثاني');body=`<article class="card reading"><span class="pill violet">${t('PHYSICS · 5 MIN','فيزياء · 5 دقائق')}</span><h2>${title}</h2><p>${graphs?t('A force–acceleration graph reveals how mass affects motion. With constant mass, doubling force doubles acceleration. The slope of a force versus acceleration graph is the mass.','يوضح منحنى القوة والتسارع تأثير الكتلة على الحركة. عند ثبات الكتلة، مضاعفة القوة تضاعف التسارع. ميل منحنى القوة بالنسبة للتسارع يساوي الكتلة.'):t('A net force changes an object’s motion. Newton’s second law connects force, mass and acceleration:','تغيّر القوة المحصلة حركة الجسم. يربط قانون نيوتن الثاني بين القوة والكتلة والتسارع:')}</p><div class="lesson-tile" style="text-align:center;font-size:30px" dir="ltr">F = m × a</div><p>${t('Example: a 2 kg cart pushed with a net force of 10 N accelerates at 5 m/s². If the mass doubles while force stays the same, acceleration halves.','مثال: عربة كتلتها 2 كغ تؤثر عليها قوة محصلة 10 نيوتن تتسارع بمقدار 5 م/ث². إذا تضاعفت الكتلة وثبتت القوة، يقل التسارع إلى النصف.')}</p><button class="btn" data-action="lesson">${t('Mark complete & practice','أكمل الدرس وابدأ التدريب')}</button></article>`}
if(page==='practice'){title=homework?t('Maths worksheet 5','ورقة الرياضيات 5'):t('Practice: force and acceleration','تدريب: القوة والتسارع');body=`<form class="card reading" id="practice-form"><h2>${t('Your turn','دورك الآن')}</h2><p>${homework?t('Solve: 3x + 6 = 21. What is x?','حل: 3x + 6 = 21. ما قيمة x؟'):t('A 4 kg object is pushed with a net force of 20 N. What is its acceleration in m/s²?','جسم كتلته 4 كغ تؤثر عليه قوة محصلة 20 نيوتن. ما تسارعه بوحدة م/ث²؟')}</p><label for="answer">${t('Your answer','إجابتك')}</label><input id="answer" class="form-field" type="number" step="any" required><button class="btn" type="submit">${t('Check & submit','تحقق وسلّم')}</button><p id="practice-feedback" role="status"></p>${btn(t('Continue to the lab','تابع إلى المختبر'),'../lab/lab.html','outline')}</form>`}
if(page==='lab'){title=t('Interactive lab: force & acceleration','مختبر تفاعلي: القوة والتسارع');body=`<section class="card reading"><p>${t('Keep force constant and increase mass. Observe how acceleration changes.','ثبّت القوة وزد الكتلة. راقب تغير التسارع.')}</p><label for="mass">${t('Mass','الكتلة')} <output id="mass-value">2 kg</output></label><input class="form-field" id="mass" type="range" min="1" max="10" value="2"><label for="force">${t('Net force','القوة المحصلة')} <output id="force-value">10 N</output></label><input class="form-field" id="force" type="range" min="0" max="50" value="10"><p dir="ltr" id="accel">a = 10 ÷ 2 = 5.00 m/s²</p><div class="sim"><div class="sim-block" id="sim-block">2 kg</div></div><p><button class="btn" data-action="simulate">${t('Run experiment','شغّل التجربة')}</button> ${btn(t('Take the quiz','ابدأ الاختبار'),'../quiz/quiz.html','outline')}</p></section>`}
if(page==='quiz'){title=t('Quiz: forces','اختبار: القوى');const qs=[[t('What is the SI unit of force?','ما وحدة القوة في النظام الدولي؟'),[t('Newton','نيوتن'),t('Kilogram','كيلوغرام'),t('Metre','متر')]],[t('10 N acting on 2 kg produces acceleration of…','قوة 10 نيوتن على كتلة 2 كغ تنتج تسارعًا قدره…'),['20 m/s²','5 m/s²','2 m/s²']],[t('If net force is zero, acceleration is…','إذا كانت القوة المحصلة صفرًا، فإن التسارع…'),[t('Zero','صفر'),t('Increasing','متزايد'),t('Always 10','دائمًا 10')]]];body=`<form id="quiz-form" class="card reading">${qs.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${q[0]}</legend>${q[1].map((a,j)=>`<label><input type="radio" name="q${i}" value="${j}" required> ${a}</label>`).join('')}</fieldset>`).join('')}<button class="btn" type="submit">${t('Submit quiz','سلّم الاختبار')}</button></form>`}
if(page==='result'){title=t('Your result','نتيجتك');body=state.quiz?`<section class="card reading"><span class="pill green">${t('Quiz completed','اكتمل الاختبار')}</span><h1>${state.quiz.score}%</h1><p>${t(`You answered ${state.quiz.correct} of 3 questions correctly.`, `أجبت بشكل صحيح عن ${state.quiz.correct} من 3 أسئلة.`)}</p><p>${t('Answers: Newton · 5 m/s² · Zero acceleration. Review the lesson and try again whenever you want.','الإجابات: نيوتن · 5 م/ث² · تسارع صفر. راجع الدرس وأعد المحاولة متى أردت.')}</p>${btn(t('Back to Physics class','العودة لصف الفيزياء'),'../class-details/class-details.html')} ${btn(t('Try again','حاول مجددًا'),'../quiz/quiz.html','outline')}</section>`:`<div class="card empty">${t('Complete the quiz to see your result.','أكمل الاختبار لعرض نتيجتك.')} ${btn(t('Start quiz','ابدأ الاختبار'),'../quiz/quiz.html')}</div>`}
if(page==='achievements'){title=t('Your achievements','إنجازاتك');body=`<section class="card"><p>${t('9 badges unlocked · 24 to collect','9 شارات مكتسبة · 24 شارة للتجميع')}</p><div class="badges">${Array.from({length:24},(_,i)=>badge(i<9?'★':'♧',i<9?['#ffa500','#8235f8','#0cbc8b'][i%3]:'#bcc6d7',`${i+1}`,i<9?t('Unlocked','مكتسبة'):t('Locked','مقفلة'))).join('')}</div></section>`}
if(page==='exchange'){title=t('Student exchange','تبادل الطلاب');body=`<div class="lesson-grid">${[[t('Physics 9 textbook','كتاب فيزياء 9'),'5 JD'],[t('Geometry set','طقم هندسة'),'3 JD']].map(r=>`<section class="card reading">${icon('▣','blue')}<h2>${r[0]}</h2><p>${r[1]} · ${t('Demo listing','إعلان تجريبي')}</p><button class="btn" data-action="reserve" data-item="${esc(r[0])}">${t('Save interest','احفظ اهتمامك')}</button></section>`).join('')}</div><p class="muted">${t('Interest is saved on this device. Contact and payment require your school’s exchange service.','يُحفظ اهتمامك على هذا الجهاز. التواصل والدفع يحتاجان خدمة التبادل الخاصة بمدرستك.')}</p>`}
if(page==='messages'){title=t('Messages','الرسائل');body=`<section class="card reading"><h2>${t('Mr. Khaled','الأستاذ خالد')}</h2><p>${t('Great progress! In Homework 2 you scored 82%. Remember to include units in every answer.','تقدم رائع! حصلت على 82% في الواجب 2. تذكر كتابة الوحدات في كل إجابة.')}</p></section>`}
if(page==='login'){title=t('Welcome to ORBIT','أهلًا بك في ORBIT');body=`<form id="login-form" class="card reading"><label for="student-name">${t('Student name','اسم الطالب')}</label><input id="student-name" class="form-field" value="${esc(state.name)}" maxlength="40" required><p class="muted">${t('Local demo profile — name and preferences stay on this device.','ملف تجريبي محلي — يُحفظ الاسم والإعدادات على هذا الجهاز.')}</p><button class="btn">${t('Enter dashboard','الدخول للوحة الطالب')}</button></form>`}
return `<header class="page-head"><a class="link" href="../student-dashboard/student-dashboard.html">← ${t('Dashboard','لوحة الطالب')}</a><h1>${title}</h1></header>${stages.includes(page)?cycleNav():''}${body}`}
function render(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.body.dataset.theme=state.theme;document.body.dataset.mood=state.mood;document.title=`ORBIT · ${t('Student space','مساحة الطالب')}`;const navs=[['◫','Dashboard','لوحة الطالب','student-dashboard'],['▣','Lessons','الدروس','lessons'],['♧','Lab','المختبر','lab'],['◉','My classes','صفوفي','class-details'],['♙','Achievements','الإنجازات','achievements'],['▤','Exchange','التبادل','exchange']];document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="../student-dashboard/student-dashboard.html"><span class="logo">♧</span><div><strong>ORBIT</strong><small>${t('Learn and level up','تعلم وارتقِ')}</small></div></a><div class="level"><div class="level-top">${icon('L7')}<div><b>${t('Level 7 · Explorer','المستوى 7 · مستكشف')}</b><br><small>${t('Physics · Your orbit','الفيزياء · مدارك')}</small></div></div><div class="bar"><span style="width:${Math.min(100,state.xp/20)}%"></span></div><div class="level-foot"><span>${state.xp.toLocaleString()} XP</span><span>2,000 XP</span></div></div><nav aria-label="${t('Main navigation','التنقل الرئيسي')}">${navs.map(n=>`<a href="${orbitRoute(n[3]+'.html')}" class="${page===n[3]?'active':''}"><span aria-hidden="true">${n[0]}</span>${t(n[1],n[2])}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="streak">${icon('♨')}<div><b>${t('5 day streak','5 أيام متتالية')}</b><small>${t('Study today to keep it','تعلم اليوم لتحافظ عليها')}</small></div></div><button class="settings" data-action="settings">⚙ ${t('Settings','الإعدادات')}</button></div></aside><main class="main"><header class="topbar"><input class="search" id="search" aria-label="${t('Search lessons','ابحث في الدروس')}" placeholder="⌕ ${t('Search lessons, classes, teachers','ابحث عن دروس، صفوف، معلمين')}"><div class="top-right"><span class="pill gold">ϟ ${state.xp.toLocaleString()} XP</span><div class="controls"><button data-action="language" aria-label="${t('Switch to Arabic','التبديل إلى الإنجليزية')}">${state.lang==='en'?'عربي':'EN'}</button><button data-action="theme" aria-label="${t('Toggle color theme','تبديل المظهر')}">${state.theme==='dark'?'☀':'☾'}</button><button data-action="mood" aria-label="${t('Toggle fun or calm mood','تبديل المرح والهدوء')}">${state.mood==='fun'?'☺':'◌'}</button><a class="btn outline" href="../channels/channels.html" aria-label="${t('Messages','الرسائل')}">♧</a></div><a class="user" href="../login/login.html"><span class="avatar">${initials()}</span><div><strong>${esc(state.name)}</strong><small>${t('Grade 9A','الصف 9A')}</small></div></a></div></header><div class="content">${page==='student-dashboard'||page==='index'?dashboard():contentPage()}<div class="footer">ORBIT · ${t('Small steps. Bigger possibilities.','خطوات صغيرة. إمكانيات أكبر.')}</div></div></main></div><dialog id="settings-dialog"><h2>${t('Your preferences','إعداداتك')}</h2>${[['lang',t('Language','اللغة'),[['en','English'],['ar','العربية']]],['theme',t('Appearance','المظهر'),[['light',t('Light','فاتح')],['dark',t('Dark','داكن')]]],['mood',t('Orbit mood','مزاج ORBIT'),[['fun',t('Fun','مرح')],['calm',t('Calm','هادئ')]]]].map(r=>`<label class="setting-row">${r[1]}<select data-setting="${r[0]}">${r[2].map(o=>`<option value="${o[0]}" ${state[r[0]]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label>`).join('')}<a class="btn outline" href="../login/login.html">${t('Edit student name','تعديل اسم الطالب')}</a><button class="btn" data-action="close">${t('Done','تم')}</button></dialog>`;bindForms()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(['language','theme','mood'].includes(a)){const key={language:'lang',theme:'theme',mood:'mood'}[a];state[key]=a==='language'?(state.lang==='en'?'ar':'en'):a==='theme'?(state.theme==='light'?'dark':'light'):(state.mood==='fun'?'calm':'fun');save();render();if(a==='mood')toast(t(`Mood: ${state.mood}`,state.mood==='fun'?'وضع المرح':'وضع الهدوء'))}if(a==='settings')document.getElementById('settings-dialog').showModal();if(a==='close')document.getElementById('settings-dialog').close();if(a==='feedback')location.href='../channel/channel.html?id=9b';if(a==='lesson'){award('lesson',20);location.href='../practice/practice.html'}if(a==='reserve'){storage.set('orbit.exchange.interest',b.dataset.item);toast(t('Interest saved on this device.','تم حفظ اهتمامك على هذا الجهاز.'))}if(a==='simulate'){const m=+document.getElementById('mass').value,f=+document.getElementById('force').value;const el=document.getElementById('sim-block');const room=el.parentElement.clientWidth-100;el.style.transform=`translateX(${(state.lang==='ar'?-1:1)*Math.min(room,f/m*12)}px)`;award('lab',15);setTimeout(()=>el.style.transform='',1400)}});
document.addEventListener('change',e=>{if(e.target.dataset.setting){state[e.target.dataset.setting]=e.target.value;save();render();document.getElementById('settings-dialog').showModal()}});
document.addEventListener('input',e=>{if(['mass','force'].includes(e.target.id)){let m=+document.getElementById('mass').value,f=+document.getElementById('force').value;document.getElementById('mass-value').textContent=m+' kg';document.getElementById('force-value').textContent=f+' N';document.getElementById('accel').textContent=`a = ${f} ÷ ${m} = ${(f/m).toFixed(2)} m/s²`;document.getElementById('sim-block').textContent=m+' kg'}if(e.target.id==='search'){const q=e.target.value.toLowerCase().trim();document.querySelectorAll('.lesson-tile').forEach(el=>el.hidden=!!q&&!el.textContent.toLowerCase().includes(q))}});
document.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Enter')location.href='../lessons/lessons.html'});
function bindForms(){document.getElementById('login-form')?.addEventListener('submit',e=>{e.preventDefault();const name=document.getElementById('student-name').value.trim();if(!name)return;state.name=name;save();location.href='../student-dashboard/student-dashboard.html'});document.getElementById('practice-form')?.addEventListener('submit',e=>{e.preventDefault();const ok=+document.getElementById('answer').value===5;const homework=new URLSearchParams(location.search).get('task')==='homework';document.getElementById('practice-feedback').textContent=ok?t('Correct! Your work has been saved.','صحيح! تم حفظ إجابتك.'):t('Try again. Divide both sides by 3, or use a = F / m.','حاول مجددًا. اقسم الطرفين على 3، أو استخدم a = F / m.');if(ok)award(homework?'homework':'practice',homework?30:50)});document.getElementById('quiz-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);let correct=0;[0,1,0].forEach((a,i)=>{if(+data.get('q'+i)===a)correct++});state.quiz={correct,score:Math.round(correct/3*100),date:new Date().toISOString()};award('quiz',30);save();location.href='../result/result.html'})}
let idle;function resetIdle(){clearTimeout(idle);idle=setTimeout(()=>{if(state.mood==='fun'&&!document.hidden)toast(t('Sleepy? 😴 A little lesson will wake your orbit!','مالك نعست؟ 😴 درس صغير يصحصح مدارك!'))},180000)}['pointerdown','keydown'].forEach(ev=>document.addEventListener(ev,resetIdle));resetIdle();render();

