const catalog=[{id:'physics',en:'Physics, in motion',ar:'الفيزياء بحركة',subject:'physics',teacher:'khaled',private:false,code:'',symbol:'⚛',color:'purple',descEn:'Understand the world. One experiment at a time.',descAr:'افهم العالم، تجربة بعد تجربة.'},{id:'9b',en:'Grade 9B · Physics',ar:'تاسع باء · فيزياء',subject:'physics',teacher:'khaled',private:true,code:'ORBIT9B',symbol:'↗',color:'blue',descEn:'Our classroom, beyond the classroom.',descAr:'صفنا الدراسي، خارج حدود الصف.'},{id:'math',en:'The maths studio',ar:'استوديو الرياضيات',subject:'math',teacher:'sara',private:false,code:'',symbol:'∑',color:'peach',descEn:'Big ideas. Simple steps.',descAr:'أفكار كبيرة، بخطوات بسيطة.'}];
