let db=Object.assign({joined:['physics','9b'],likes:[],saved:[],comments:{},role:'student',channels:[],posts:[]},parsed('orbit.channels.v2')||{});
const allChannels=()=>[...catalog,...db.channels],persist=()=>storage.set('orbit.channels.v2',JSON.stringify(db));
