const label=x=>esc(state.lang==='ar'?x.ar:x.en),person=id=>people.find(p=>p.id===id)||people[0],channelURL=c=>`../channel/channel.html?id=${encodeURIComponent(c.id)}`,subj=s=>({physics:t('Physics','الفيزياء'),math:t('Mathematics','الرياضيات'),arabic:t('Arabic','اللغة العربية'),english:t('English','اللغة الإنجليزية'),chemistry:t('Chemistry','الكيمياء'),biology:t('Biology','الأحياء')})[s]||t('Education','التعليم');
