function chCard(c){return `<a class="channel-card ${c.color}" href="${channelURL(c)}"><div class="channel-top"><span class="channel-symbol">${esc(c.symbol)}</span><span class="pill">${c.private?t('◈ Private','◈ خاصة'):t('◎ Public','◎ عامة')}</span></div><h3>${label(c)}</h3><p>${esc(state.lang==='ar'?c.descAr:c.descEn)}</p><div class="channel-foot"><span class="mini-avatar">${person(c.teacher).letters}</span>${label(person(c.teacher))}<span class="arrow">↗</span></div></a>`}
function postCard(p){const c=allChannels().find(c=>c.id===p.channel);if(!c)return'';const teacher=person(c.teacher),liked=db.likes.includes(p.id),saved=db.saved.includes(p.id),comments=db.comments[p.id]||[];return `<article class="post card" data-post="${esc(p.id)}"><header class="post-head"><a class="mini-avatar ${c.color}" href="../teacher-profile/teacher-profile.html?id=${teacher.id}">${teacher.letters}</a><div><a class="post-author" href="../teacher-profile/teacher-profile.html?id=${teacher.id}">${label(teacher)}</a><a class="post-channel" href="${channelURL(c)}">${label(c)} · ${typeName(p.type)}</a></div><button class="icon-button ${saved?'selected':''}" data-v2="save" data-id="${esc(p.id)}" aria-pressed="${saved}" aria-label="${t('Save post','حفظ المنشور')}">${saved?'◆':'◇'}</button></header><h2>${esc(state.lang==='ar'?(p.titleAr||p.title):(p.titleEn||p.title))}</h2><p class="post-body">${esc(state.lang==='ar'?(p.bodyAr||p.body):(p.bodyEn||p.body))}</p>${p.type==='lesson'?`<a class="lesson-preview" href="../lesson/lesson.html"><span class="play-circle">▷</span><div><strong>${t('A little curiosity goes a long way.','قليل من الفضول يفتح عالمًا.')}</strong><small>${t('Interactive lesson · 5 min','درس تفاعلي · 5 دقائق')}</small></div><span class="preview-atom">⚛</span></a>`:''}${p.type==='video'&&(p.url||p.videoAsset)?`<video controls preload="metadata" src="${esc(p.url||'')}" data-orbit-media="${esc(p.videoAsset||'')}"></video>`:''}${p.type==='assignment'?`<div class="assignment-preview"><span>${t('Ready for your next step?','جاهز للخطوة القادمة؟')}</span>${btn(t('Open assignment','افتح الواجب'),'../practice/practice.html')}</div>`:''}<footer class="post-actions"><button class="reaction ${liked?'selected':''}" data-v2="like" data-id="${esc(p.id)}" aria-pressed="${liked}">${liked?'♥':'♡'} ${p.likes+Number(liked)}</button><button class="reaction" data-v2="comment" data-id="${esc(p.id)}">☏ ${comments.length} ${t('Comments','تعليقات')}</button><span class="muted">${t('Demo classroom activity','نشاط صفّي تجريبي')}</span></footer>${comments.length?`<div class="comments">${comments.map(m=>`<p><b>${esc(m.authorId?OrbitProfiles.read(m.authorId).name||m.name:m.name)}</b> ${esc(m.text)}</p>`).join('')}</div>`:''}<form class="comment-form" data-comment="${esc(p.id)}" hidden><label class="sr-only" for="comment-${esc(p.id)}">${t('Your comment','تعليقك')}</label><input id="comment-${esc(p.id)}" name="comment" required maxlength="300" placeholder="${t('Add to the conversation…','شارك بالنقاش…')}"><button class="btn">${t('Post','نشر')}</button></form></article>`}
