dashboard=()=>`<div class="welcome-line"><div><span class="eyebrow">${t('YOUR LEARNING ORBIT','مدارك التعليمي')}</span><h1>${t('Good to see you','أهلًا برجعتك')}, ${esc(state.name)} <span class="wave">✦</span></h1></div><button class="btn outline" data-v2="join">＋ ${t('Join a channel','انضم لقناة')}</button></div><section class="orbit-hero"><div class="hero-copy"><span class="hero-kicker">✧ ${t('A new idea is waiting for you','فكرة جديدة بانتظارك')}</span><h2>${t('Your next discovery<br>starts with a channel.','اكتشافك القادم<br>يبدأ من قناة.')}</h2><p>${t('Your teachers. Your questions. A whole world to explore.','أساتذتك، أسئلتك، وعالم كامل لتكتشفه.')}</p><div class="actions">${btn(t('Explore channels','استكشف القنوات')+' ↗','../channels/channels.html','white-button')}${btn(t('Continue learning','تابع التعلم'),'../lesson/lesson.html','secondary')}</div></div><div class="orbital-art" aria-hidden="true"><div class="orbit-line one"></div><div class="orbit-line two"></div><span class="orbit-dot"></span><div class="planet">⚛</div><div class="floating-note note-a">ϟ <b>+${state.xp.toLocaleString()} XP</b></div><div class="floating-note note-b">✓ ${t('Keep growing','واصل التقدم')}</div><span class="star s1">✧</span><span class="star s2">✦</span></div></section><div class="metric-strip">${[['♨','amber','5',t('day streak','أيام متتالية')],['ϟ','violet',state.xp.toLocaleString(),'XP'],['◎','mint',db.joined.length,t('channels joined','قنواتك')],['♙','pink',9+Number(state.done.includes('quiz')),t('badges earned','شارات مكتسبة')]].map(x=>`<div><span class="metric-icon ${x[1]}">${x[0]}</span><strong>${x[2]}<small>${x[3]}</small></strong></div>`).join('')}</div><div class="section-heading"><div><h2>${t('Your channels','قنواتك')}</h2><span>${t('A little closer to your teachers.','أقرب لأساتذتك، كل يوم.')}</span></div><a class="link" href="../channels/channels.html">${t('View all','عرض الكل')} ↗</a></div><div class="channel-grid">${allChannels().filter(c=>db.joined.includes(c.id)).map(chCard).join('')||`<div class="card">${t('Join your first channel to begin.','انضم لأول قناة لتبدأ.')}</div>`}</div><div class="feed-layout"><div><div class="section-heading"><h2>${t('Fresh from your teachers','جديد أساتذتك')}</h2><span class="live-dot">${t('Your feed','منشوراتك')}</span></div>${allPosts().filter(p=>db.joined.includes(p.channel)).slice(0,4).map(postCard).join('')}</div><aside class="stack companion"><section class="card mission-card"><span class="eyebrow">${t('TODAY’S SMALL WIN','إنجازك الصغير اليوم')}</span><h2>${t('A little effort.<br>A bigger orbit.','جهد صغير.<br>ومدار أكبر.')}</h2><div class="mission-progress"><strong>${Math.min(100,60+state.done.length*10)}%</strong><div class="bar"><span style="width:${Math.min(100,60+state.done.length*10)}%"></span></div></div><p>${t('Finish a lesson or try an experiment. Your progress adds up.','أنهِ درسًا أو جرّب تجربة. كل خطوة تفرق.')}</p>${btn(t('Try the force lab','جرّب مختبر القوى')+' ↗','../lab/lab.html')}</section><section class="card"><div class="card-title"><h2>${t('Your next lesson','درسك القادم')}</h2><span class="pill violet">5 ${t('min','دقائق')}</span></div>${lessonTile(t('Newton’s laws','قوانين نيوتن'),t('Physics 11','فيزياء 11'),'⚛',60,'../lesson/lesson.html','3 / 5',20)}</section><section class="card"><h2>${t('Class leaderboard','متصدرو الصف')}</h2>${[['RM',t('Rami','رامي'),1640],['OK',t('Omar','عمر'),1410],[initials(),t('You','أنت'),state.xp]].sort((a,b)=>b[2]-a[2]).map((r,i)=>`<div class="rank ${r[1]===t('You','أنت')?'you':''}"><span class="place">${i+1}</span><span class="avatar">${r[0]}</span>${r[1]}<span class="points">${r[2]}</span></div>`).join('')}</section><a href="../exchange/exchange.html" class="exchange-teaser">◇ ${t('Give a book a new orbit.','امنح كتابًا مدارًا جديدًا.')}<span>${t('Visit the exchange','تصفح التبادل')} ↗</span></a></aside></div>`;
contentPage=()=>{let title='',body='';if(page==='channels'){title=t('Find your next orbit.','اكتشف مدارك القادم.');body=`<div class="toolbar"><div class="tabs">${[['all',t('All channels','كل القنوات')],['joined',t('My channels','قنواتي')],['public',t('Public','عامة')],['saved',t('Saved posts','المحفوظات')]].map((x,i)=>`<button class="tab ${i===0?'active':''}" data-filter="${x[0]}">${x[1]}</button>`).join('')}</div><button class="btn" data-v2="join">＋ ${t('Join with a code','انضم بكود')}</button></div><div class="channel-grid directory" id="channel-directory">${allChannels().map(c=>`<div data-channel-card data-private="${c.private}" data-joined="${db.joined.includes(c.id)}">${chCard(c)}</div>`).join('')}</div><div id="saved-posts" hidden>${allPosts().filter(p=>db.saved.includes(p.id)&&allChannels().some(c=>c.id===p.channel&&(!c.private||db.joined.includes(c.id)))).map(postCard).join('')||`<div class="card empty">${t('Save a post to find it here.','احفظ منشورًا لتجده هنا.')}</div>`}</div><p class="demo-hint">${t('Private demo classroom code:','كود الصف الخاص التجريبي:')} <b dir="ltr">ORBIT9B</b></p>`}
else if(page==='channel'){const c=currentChannel(),joined=db.joined.includes(c.id),teach=db.role==='teacher';title=label(c);body=`<section class="channel-banner ${c.color}"><span class="channel-symbol">${c.symbol}</span><div><span class="eyebrow">${c.private?t('PRIVATE CLASSROOM','صف خاص'):t('PUBLIC CHANNEL','قناة عامة')}</span><h2>${label(c)}</h2><p>${esc(state.lang==='ar'?c.descAr:c.descEn)}</p><a href="../teacher-profile/teacher-profile.html?id=${c.teacher}" class="link">${label(person(c.teacher))} ↗</a></div><button class="btn ${joined?'outline':''}" data-v2="${joined?'leave':c.private?'join':'follow'}" data-id="${esc(c.id)}">${joined?t('✓ Joined · leave','✓ عضو · مغادرة'):t('Join channel','انضم للقناة')}</button></section>${c.private&&!joined&&!teach?`<section class="card locked"><span>◈</span><h2>${t('A space just for your classroom.','مساحة خاصة بصفك.')}</h2><p>${t('Enter your teacher’s code to see the posts.','أدخل كود المعلم لعرض المنشورات.')}</p><button class="btn" data-v2="join">${t('Enter code','أدخل الكود')}</button></section>`:`${teach?`<div class="toolbar"><span class="muted">${t('Teacher demo view','عرض المعلم التجريبي')}</span><button class="btn" data-v2="compose" data-id="${esc(c.id)}">＋ ${t('Create a post','أضف منشورًا')}</button></div>`:''}<div class="channel-posts">${allPosts().filter(p=>p.channel===c.id).map(postCard).join('')||`<div class="card empty">${t('Your first post starts the conversation.','منشورك الأول يبدأ الحوار.')}</div>`}</div>`}`}
else if(page==='teacher-studio'){title=t('Your teaching, in one place.','كل شغلك التعليمي، بمكان واحد.');body=db.role!=='teacher'?`<div class="card"><p>${t('Switch the demo role to Teacher in the sidebar to explore the studio.','اختر دور المعلم التجريبي من القائمة الجانبية لتجربة الاستوديو.')}</p></div>`:`<section class="studio-intro"><div><span class="eyebrow">${t('TEACHER STUDIO','استوديو المعلم')}</span><h2>${t('Teach. Share. Get discovered.','علّم. شارك. خلّي شغلك يحكي.')}</h2><p>${t('Create a classroom or share your ideas with the world.','أنشئ مساحة لصفك، أو شارك أفكارك مع الجميع.')}</p></div><button class="btn" data-v2="create">＋ ${t('Create channel','أنشئ قناة')}</button></section><div class="channel-grid directory">${allChannels().filter(c=>c.teacher==='khaled').map(c=>`<section>${chCard(c)}<div class="studio-actions"><a class="link" href="${channelURL(c)}">${t('Manage & post','الإدارة والنشر')} ↗</a>${c.private?`<span class="pill violet" dir="ltr">${esc(c.code)}</span>`:''}</div></section>`).join('')}</div><section class="card plan-card"><div><span class="pill gold">ORBIT PLUS · ${t('Concept','تصور')}</span><h2>${t('More room for your ideas.','مساحة أكبر لأفكارك.')}</h2><p>${t('Longer videos, more storage and richer insights. No payment is connected in this demo.','فيديوهات أطول، مساحة أكبر وتحليلات أوسع. الدفع غير مربوط في هذه النسخة.')}</p></div><button class="btn outline" data-v2="premium">${t('Explore Plus','اكتشف Plus')}</button></section>`}
else if(page==='teachers'){title=t('Discover the teacher behind the lesson.','اكتشف المعلم وراء الدرس.');body=`<section class="teacher-filters card"><label>${t('Subject','التخصص')}<select id="teacher-subject"><option value="all">${t('All subjects','جميع التخصصات')}</option><option value="physics">${subj('physics')}</option><option value="math">${subj('math')}</option>${['arabic','english','chemistry','biology'].map(s=>`<option value="${s}">${subj(s)}</option>`).join('')}</select></label><label>${t('Experience','الخبرة')}<select id="teacher-exp"><option value="0">${t('Any experience','أي خبرة')}</option><option value="6">${t('6+ years','6 سنوات فأكثر')}</option></select></label></section><div class="teacher-grid">${people.map(p=>`<article class="teacher-card card" data-teacher data-subject="${p.subject}" data-exp="${p.experience}"><div class="teacher-cover ${p.style}">✧</div><span class="profile-avatar ${p.style}">${p.letters}</span><h2>${label(p)}</h2><span class="pill violet">${subj(p.subject)}</span><p>${esc(state.lang==='ar'?p.bioAr:p.bioEn)}</p><div class="teacher-meta">${p.experience} ${t('years · Secondary education','سنوات · تعليم ثانوي')}</div>${btn(t('View teaching portfolio','شاهد الملف المهني')+' ↗','../teacher-profile/teacher-profile.html?id='+p.id,'outline')}</article>`).join('')}</div><p id="teacher-empty" class="empty" hidden>${t('No teachers match these filters.','لا يوجد معلمون يطابقون الفلاتر.')}</p><p class="demo-hint">${t('Explore teachers by subject and experience. Credentials are self-reported, not verified.','ابحث عن المعلمين حسب المادة والخبرة. المؤهلات معلنة ذاتيًا وغير موثقة.')}</p>`}
else if(page==='teacher-profile'){const p=person(new URLSearchParams(location.search).get('id'));title=label(p);body=`<section class="profile-header card"><div class="profile-cover ${p.style}"><span>✧</span><span>${t('TEACHING IS A CREATIVE ACT.','التعليم فعل إبداعي.')}</span></div><div class="profile-detail"><span class="profile-avatar ${p.style}">${p.letters}</span><div><span class="pill violet">${subj(p.subject)}</span><h2>${label(p)}</h2><p>${esc(state.lang==='ar'?p.bioAr:p.bioEn)}</p></div></div></section><div class="profile-layout"><section class="card"><h2>${t('Experience & education','الخبرة والتعليم')}</h2><p>${p.experience} ${t('years of teaching','سنوات تدريس')}</p><p>${esc(state.lang==='ar'?p.degreeAr:p.degreeEn)}</p><span class="pill gold">${t('Self-reported · unverified','مؤهلات معلنة ذاتيًا · غير موثقة')}</span><p class="muted">${t('Public teaching samples only. Private student work stays in the classroom.','نماذج تدريس عامة فقط. أعمال الطلاب الخاصة تبقى داخل الصف.')}</p></section><section><div class="section-heading"><h2>${t('Teaching in action','التدريس على أرض الواقع')}</h2></div>${allPosts().filter(post=>allChannels().some(c=>c.id===post.channel&&c.teacher===p.id&&!c.private)).map(postCard).join('')||'<p class="empty-state">'+t('No public teaching posts yet.','لسه ما في منشورات تعليمية عامة.')+'</p>'}</section></div>`}
else return basePage();return `<header class="page-head"><span class="eyebrow">ORBIT / ${t('CONNECTED LEARNING','تعلم متصل')}</span><h1>${title}</h1></header>${body}`};
render=()=>{baseRender();const nav=document.querySelector('.sidebar nav');const items=db.role==='teacher'?[['◎',t('My channels','قنواتي'),'channels'],['✧',t('Teacher studio','استوديو المعلم'),'teacher-studio'],['↗',t('My portfolio','ملفي المهني'),'teacher-profile?id=khaled']]:[['◎',t('My channels','قنواتي'),'channels'],['✧',t('Teacher discovery','اكتشف المعلمين'),'teachers']];items.reverse().forEach(n=>{const a=document.createElement('a'),parts=n[2].split('?');a.href=orbitRoute(parts[0]+'.html'+(parts[1]?'?'+parts[1]:''));a.className=page===parts[0]?'active':'';a.innerHTML=`<span>${n[0]}</span>${n[1]}`;nav.prepend(a)});document.querySelector('.controls a[href="../channels/channels.html"]')?.remove();document.querySelector('.content').insertAdjacentHTML('beforeend','<dialog id="channel-dialog"></dialog>');document.querySelectorAll('.card,.channel-card').forEach((el,i)=>el.style.setProperty('--delay',`${Math.min(i,6)*45}ms`));document.querySelectorAll('[data-comment]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();const text=new FormData(f).get('comment').trim();if(!text)return;const id=f.dataset.comment;db.comments[id]??=[];db.comments[id].push({name:OrbitProfiles.current()?.name||state.name,authorId:OrbitAuth.current()?.email,text});persist();render()}))};
function modal(html){const d=document.getElementById('channel-dialog');d.innerHTML=`<button class="dialog-close" data-v2="close" aria-label="${t('Close','إغلاق')}">×</button>${html}`;d.showModal();d.querySelector('input,textarea,select,button:not(.dialog-close)')?.focus()}
function field(id,name){return `<label class="modal-field">${name}<input name="${id}" required maxlength="100"></label>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-v2]');if(!b)return;const a=b.dataset.v2,id=b.dataset.id;
if(a==='close')document.getElementById('channel-dialog').close();
if(a==='join'){modal(`<span class="eyebrow">${t('YOUR CLASSROOM AWAITS','صفك بانتظارك')}</span><h2>${t('Enter your channel code','أدخل كود قناتك')}</h2><form id="join-form">${field('code',t('Code from your teacher','الكود من معلمك'))}<p class="muted">${t('Demo code: ORBIT9B','كود تجريبي: ORBIT9B')}</p><p id="join-error" role="status"></p><button class="btn">${t('Join channel','انضم للقناة')} ↗</button></form>`);document.getElementById('join-form').addEventListener('submit',e=>{e.preventDefault();const code=new FormData(e.target).get('code').trim().toUpperCase(),c=allChannels().find(c=>c.private&&c.code===code);if(!c){document.getElementById('join-error').textContent=t('Code not found. Check it and try again.','الكود غير موجود. تأكد منه وحاول مجددًا.');return}if(!db.joined.includes(c.id))db.joined.push(c.id);persist();location.href=channelURL(c)})}
if(a==='follow'||a==='leave'){db.joined=a==='leave'?db.joined.filter(x=>x!==id):[...new Set([...db.joined,id])];persist();render();toast(a==='leave'?t('Channel left.','غادرت القناة.'):t('Welcome to your new orbit!','أهلًا في مدارك الجديد!'))}
if(a==='like'||a==='save'){const key=a==='like'?'likes':'saved';db[key]=db[key].includes(id)?db[key].filter(x=>x!==id):[...db[key],id];persist();const y=scrollY;render();window.scrollTo(0,y);if(a==='save')toast(t('Saved posts stay on this device.','تُحفظ المنشورات على هذا الجهاز.'))}
if(a==='comment'){const f=document.querySelector(`[data-comment="${id}"]`);f.hidden=!f.hidden;if(!f.hidden)f.querySelector('input').focus()}
if(a==='premium')modal(`<span class="pill gold">ORBIT PLUS</span><h2>${t('Room to grow.','مساحة لتكبر.')}</h2><p>${t('Proposed features: longer videos, additional channels, storage and learning analytics. No paid plan, billing or upload limits are connected in this demo.','ميزات مقترحة: فيديوهات أطول، قنوات إضافية، تخزين أكبر وتحليلات تعلم. الاشتراك والفوترة وحدود الرفع غير مربوطة في النموذج.')}</p><button class="btn" data-v2="close">${t('Got it','تمام')}</button>`);
if(a==='create'&&db.role==='teacher'){modal(`<h2>${t('Start a new orbit.','ابدأ مدارًا جديدًا.')}</h2><form id="create-form">${field('name',t('Channel name','اسم القناة'))}<label class="modal-field">${t('Who is it for?','لمن القناة؟')}<select name="visibility"><option value="public">${t('Public · everyone can view','عامة · يشاهدها الجميع')}</option><option value="private">${t('Private · join with code','خاصة · انضمام بكود')}</option></select></label><button class="btn">${t('Create channel','أنشئ القناة')} ↗</button></form>`);document.getElementById('create-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim();if(!name)return;const id='c'+Date.now().toString(36),code='ORB'+crypto.getRandomValues(new Uint32Array(1))[0].toString(36).slice(0,6).toUpperCase();db.channels.push({id,en:name,ar:name,private:f.get('visibility')==='private',code,teacher:'khaled',subject:'physics',color:'purple',symbol:'✧',descEn:'A new space to learn together.',descAr:'مساحة جديدة لنتعلم معًا.'});persist();location.href=channelURL({id})})}
if(a==='compose'&&db.role==='teacher'){modal(`<h2>${t('Share something worth discovering.','شارك شيئًا يستحق الاكتشاف.')}</h2><form id="compose-form">${field('title',t('Post title','عنوان المنشور'))}<label class="modal-field">${t('Type','النوع')}<select name="type">${['discussion','lesson','assignment','announcement','video'].map(x=>`<option value="${x}">${typeName(x)}</option>`).join('')}</select></label><label class="modal-field">${t('Your idea','فكرتك')}<textarea name="body" required maxlength="2000" rows="4"></textarea></label><label class="modal-field">${t('Optional direct HTTPS video URL','رابط فيديو HTTPS مباشر اختياري')}<input name="url" type="url" placeholder="https://…"></label><p class="muted">${t('Saved locally. Video hosting is not connected.','يُحفظ محليًا. استضافة الفيديو غير مربوطة.')}</p><p id="post-error" role="status"></p><button class="btn">${t('Publish locally','نشر محلي')} ↗</button></form>`);document.getElementById('compose-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),url=f.get('url').trim();if(url&&!/^https:\/\//i.test(url)){document.getElementById('post-error').textContent=t('Use an HTTPS video URL.','استخدم رابط فيديو HTTPS.');return}db.posts.unshift({id:'p'+Date.now().toString(36),channel:id,type:f.get('type'),title:f.get('title').trim(),body:f.get('body').trim(),url,likes:0});persist();render();toast(t('Your post is now in the channel.','منشورك صار بالقناة.'))})}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;document.querySelectorAll('.tab').forEach(el=>el.classList.toggle('active',el===b));const saved=b.dataset.filter==='saved';document.getElementById('channel-directory').hidden=saved;document.getElementById('saved-posts').hidden=!saved;document.querySelectorAll('[data-channel-card]').forEach(el=>el.hidden=b.dataset.filter==='joined'?el.dataset.joined!=='true':b.dataset.filter==='public'?el.dataset.private==='true':false)});
document.addEventListener('change',e=>{if(e.target.id==='demo-role'){db.role=e.target.value;persist();location.href=db.role==='teacher'?'../teacher-studio/teacher-studio.html':db.role==='school'?'../teacher-directory/teacher-directory.html':'../student-dashboard/student-dashboard.html'}if(['teacher-subject','teacher-exp'].includes(e.target.id)){const sub=document.getElementById('teacher-subject').value,exp=+document.getElementById('teacher-exp').value;let visible=0;document.querySelectorAll('[data-teacher]').forEach(el=>{el.hidden=(sub!=='all'&&el.dataset.subject!==sub)||+el.dataset.exp<exp;if(!el.hidden)visible++});document.getElementById('teacher-empty').hidden=visible!==0}});
const nativeAward=award;award=(id,xp)=>{const fresh=!state.done.includes(id);nativeAward(id,xp);if(fresh&&state.mood==='fun'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const sparks=document.createElement('div');sparks.className='celebration';sparks.setAttribute('aria-hidden','true');sparks.innerHTML=Array.from({length:22},(_,i)=>`<i style="--x:${(i*41)%100}%;--r:${i*27}deg;--delay:${i%5*50}ms;background:${['#8b5cf6','#ffb82e','#23d6b1'][i%3]}"></i>`).join('');document.body.append(sparks);setTimeout(()=>sparks.remove(),1500)}};
render();
// Search the channel experience without interrupting the learning-page search.
const channelPages=['student-dashboard','index','channels','channel','teachers','teacher-profile','teacher-studio'];
function searchChannels(q){q=q.trim().toLocaleLowerCase();document.querySelectorAll('.channel-card,.post,[data-teacher]').forEach(el=>{el.hidden=!!q&&!el.textContent.toLocaleLowerCase().includes(q)})}
document.addEventListener('input',e=>{if(e.target.id==='search'&&channelPages.includes(page))searchChannels(e.target.value)});
document.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Enter'&&channelPages.includes(page)){e.preventDefault();e.stopImmediatePropagation();searchChannels(e.target.value)}},true);

let orbitMediaURLs=[];const orbitIntegratedRender=render;render=()=>{orbitMediaURLs.forEach(u=>URL.revokeObjectURL(u));orbitMediaURLs=[];orbitIntegratedRender();document.querySelectorAll('video[data-orbit-media]').forEach(v=>{const key=v.dataset.orbitMedia;if(!key)return;const req=indexedDB.open('orbit-media-v1',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('videos'))req.result.createObjectStore('videos')};req.onsuccess=()=>{const d=req.result;if(!d.objectStoreNames.contains('videos')){d.close();return}const get=d.transaction('videos').objectStore('videos').get(key);get.onsuccess=()=>{if(get.result&&v.isConnected){const url=URL.createObjectURL(get.result);orbitMediaURLs.push(url);v.src=url}d.close()};get.onerror=()=>d.close()}});document.querySelectorAll('.post[data-post]').forEach(el=>{const p=db.posts.find(p=>p.id===el.dataset.post);if(p&&p.dueDate){const span=document.createElement('p');span.className='pill violet';span.textContent=t('Due: ','التسليم: ')+p.dueDate;el.querySelector('.assignment-preview')?.append(span)}});if(page==='teacher-profile'&&(!new URLSearchParams(location.search).get('id')||new URLSearchParams(location.search).get('id')==='khaled')&&orbitStoredTeacher){const card=document.querySelector('.profile-layout>.card');if(card&&orbitStoredTeacher.location){const p=document.createElement('p');p.textContent=orbitStoredTeacher.location;card.append(p)}if(card&&orbitStoredTeacher.cv){try{const u=new URL(orbitStoredTeacher.cv);if(u.protocol==='https:'){const a=document.createElement('a');a.className='btn outline';a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=t('View CV','شاهد السيرة الذاتية');card.append(a)}}catch{}}}};render();

const portfolioContentRender=render;render=()=>{portfolioContentRender();document.querySelectorAll('.post[data-post]').forEach(el=>{const p=ORBIT.db().posts.find(p=>p.id===el.dataset.post);if(ORBIT.get('orbit.deleted.posts',[]).includes(el.dataset.post)){el.remove();return}if(p?.attachments?.length){const div=document.createElement('div');div.innerHTML=ORBIT.attachment({...p,videoAsset:'',url:''});el.append(div)}});ORBIT.hydrate()};render();

window.addEventListener('orbit:profile-change',()=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.querySelector('dialog[open]'))return;for(const person of people){const p=OrbitProfiles.read(OrbitProfiles.canonical(person.id),'teacher');if(p.role!=='teacher')continue;Object.assign(person,{en:p.name,ar:p.name,subject:p.subject||'physics',experience:+p.experience||0,bioEn:p.bio||'',bioAr:p.bio||'',degreeEn:p.qualification||t('Not supplied','غير مذكور'),degreeAr:p.qualification||t('Not supplied','غير مذكور')})}render()});

window.addEventListener('orbit:profile-change',()=>{state.name=OrbitProfiles.current()?.name||state.name;if(!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]'))render()});
